def get_maxgold(M, R, C):
    if R < 1 or C < 1:
        return 0
    gold = [[0 for _ in range(C)] for _ in range(R)]
    for c in range(C):
        gold[0][c] = M[0][c]
    for r in range(1, R):
        for c in range(C):
            if c == 0:
                gold[r][c] = M[r][c] + max(gold[r - 1][c], gold[r - 1][c + 1])
            elif c == C - 1:
                gold[r][c] = M[r][c] + max(gold[r - 1][c - 1], gold[r - 1][c])
            else:
                gold[r][c] = M[r][c] + max(gold[r - 1][c - 1], gold[r - 1][c], gold[r - 1][c + 1])
    return max(gold[-1])
```

