def get_maxgold(M, R, C):
    if R < 1 or C < 1:
        return 0
    dp = [[0 for _ in range(C)] for _ in range(R)]
    for c in range(C - 2, -1, -1):
        for r in range(R):
            right = dp[r][c + 1] if c + 1 < C else 0
            down = dp[r + 1][c] if r + 1 < R else 0
            right_down = dp[r + 1][c + 1] if r + 1 < R and c + 1 < C else 0
            dp[r][c] = M[r][c] + max(right, down, right_down)
    return max(dp[0])
```

