def get_maxgold(mine, rows, cols):
    dp = [[0 for _ in range(cols)] for _ in range(rows)]
    for col in range(cols):
        dp[rows-1][col] = mine[rows-1][col]
    for row in range(rows-2, -1, -1):
        for col in range(cols):
            if col == 0:
                dp[row][col] = mine[row][col] + max(dp[row+1][col], dp[row+1][col+1])
            elif col == cols-1:
                dp[row][col] = mine[row][col] + max(dp[row+1][col], dp[row+1][col-1])
            else:
                dp[row][col] = mine[row][col] + max(dp[row+1][col], dp[row+1][col-1], dp[row+1][col+1])
    return max(dp[0])
